// 知识讲解 · 风格样片。标准分镜：标题 → 花字 → 图片容器与高亮 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、card()（白卡片与柔和投影）、marker()（荧光笔划重点）、numberBadge()（分类色序号圆）、donut()（环形图）、
// push() + group()（整屏推移换场：旧内容向左推出淡掉，新内容从右推入），以及 layers() 的分层写法：
// 每个元素在画面坐标里画，pose 只给平移与不透明度，运行时据此做运动模糊。

const STYLE = {
  color: {
    bg: "#F6F3EC", // 暖纸色，长时间看不累
    ink: "#23262E",
    muted: "#6E7380",
    card: "#FFFFFF",
    line: "#E4DFD4",
    marker: "#FFE27A", // 荧光笔，只用来划重点
    cats: ["#3E6FE6", "#F2913D", "#2FA77A"], // 三个分类色，一类一色，全片不换
  },
  font: {
    title: '"MiSans", "HarmonyOS Sans SC", "Source Han Sans SC", "Microsoft YaHei", sans-serif',
    number: '"DIN Next LT Pro", "Bahnschrift", "MiSans", sans-serif',
  },
};

// 每段一屏。旧内容向左推出、0.25 s 淡掉，新内容在它淡到一半时从右推入（两段重叠 0.05 秒），版面不会撞在一起。
const SCENES = { title: [0, 2.0], keyword: [1.95, 3.7], media: [3.65, 6.3], data: [6.25, 8.2], name: [8.15, 9.6], end: [9.55, 99] };
const COPY = {
  title: ["把想法变成", "画面"],
  keyword: { lead: "风格", key: "不走样" },
  media: "示意画面",
  data: { value: 87, unit: "%", label: "一次通过率" },
  name: { name: "痕继痕迹", role: "动效设计师" },
  end: ["一个风格，", "处处一致"],
};

const clamp = (v) => Math.max(0, Math.min(1, v));
const cubicOut = (v) => 1 - Math.pow(1 - clamp(v), 3);
const cubicIn = (v) => clamp(v) ** 3;
const cubicInOut = (v) => { v = clamp(v); return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2; };
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 温和：入场 0.5 s cubicOut，离场 0.25 s cubicIn。
function phase(t, [a, b], delay = 0, inDur = 0.5, outDur = 0.25) {
  return { enter: cubicOut((t - a - delay) / inDur), leave: cubicIn((t - (b - outDur)) / outDur), on: t >= a && t < b };
}

// 换场：整屏内容从右推入（场景开头 0.45 s，cubicInOut），离场时向左推出并淡掉。
function push(t, [a, b], w) {
  const inX = a > 0 ? (1 - cubicInOut((t - a) / 0.45)) * w * 0.12 : 0;
  return inX - cubicIn((t - (b - 0.25)) / 0.25) * w * 0.08;
}
// 一个场景里的元素：推移 + 自己的轻微上移，不透明度跟入场与离场。
function group(w, u, scene, { bounds, delay = 0, rise = 18, draw }) {
  return {
    bounds,
    pose: (t) => {
      const p = phase(t, scene, delay);
      if (!p.on || p.enter <= 0) return null;
      return { x: push(t, scene, w), y: (1 - p.enter) * rise * u, opacity: Math.min(1, p.enter * 2.5) * (1 - p.leave) };
    },
    draw,
  };
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  roundPath(ctx, x, y, w, h, r);
}
// 只追加路径不清空，用来和外框一起做 evenodd 镂空。
function roundPath(ctx, x, y, w, h, r) {
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// 白卡片：小圆角 + 一层很柔的投影，像放在纸上的卡片。
function card(ctx, x, y, w, h, u) {
  ctx.save();
  ctx.shadowColor = "rgba(60,50,30,0.12)";
  ctx.shadowBlur = 24 * u;
  ctx.shadowOffsetY = 8 * u;
  ctx.fillStyle = STYLE.color.card;
  roundRect(ctx, x, y, w, h, 14 * u);
  ctx.fill();
  ctx.restore();
}

// 荧光笔：从左到右划过关键词的下半部分，两端略不齐，像手划的（正着划，不倾斜）。baseline、size 是被划文字的基线和字号。
function marker(ctx, x, baseline, w, size, k) {
  if (k <= 0) return;
  const y = baseline - size * 0.46, h = size * 0.56;
  ctx.save();
  ctx.fillStyle = STYLE.color.marker;
  ctx.beginPath();
  const len = w * cubicOut(k);
  ctx.moveTo(x - 4, y + h * 0.06);
  ctx.lineTo(x + len, y);
  ctx.lineTo(x + len + 3, y + h);
  ctx.lineTo(x, y + h * 1.04);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function numberBadge(ctx, x, y, r, n, color) {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#FFFFFF";
  ctx.font = font(700, r * 1.05, STYLE.font.number);
  ctx.textAlign = "center";
  ctx.fillText(String(n), x, y + r * 0.37);
  ctx.textAlign = "left";
}

function donut(ctx, cx, cy, r, k, u) {
  ctx.lineCap = "round";
  ctx.lineWidth = 26 * u;
  ctx.strokeStyle = STYLE.color.line;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
  ctx.strokeStyle = STYLE.color.cats[0];
  ctx.beginPath(); ctx.arc(cx, cy, r, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * k); ctx.stroke();
}

// 示意画面：一块浅色的编辑界面（预览、属性栏、时间线），在画面坐标里画；高亮目标是属性栏里的蓝色按钮。
function mockTarget(x, y, iw, ih) { return { x: x + iw * 0.69, y: y + ih * 0.47, w: iw * 0.23, h: ih * 0.09 }; }
function mockScreen(ctx, x, y, iw, ih, u) {
  ctx.save(); roundRect(ctx, x, y, iw, ih, 8 * u); ctx.clip();
  ctx.fillStyle = "#FBFAF7"; ctx.fillRect(x, y, iw, ih);
  ctx.fillStyle = "#EFEBE3"; ctx.fillRect(x, y, iw, ih * 0.08);
  for (let i = 0; i < 3; i++) { ctx.fillStyle = "#DCD6CB"; ctx.beginPath(); ctx.arc(x + (14 + i * 13) * u, y + ih * 0.04, 3.5 * u, 0, Math.PI * 2); ctx.fill(); }
  const px = x + iw * 0.035, py = y + ih * 0.13, pw = iw * 0.6, ph = ih * 0.54;
  const sky = ctx.createLinearGradient(0, py, 0, py + ph);
  sky.addColorStop(0, "#CFDDFB"); sky.addColorStop(1, "#F1F4FB");
  ctx.fillStyle = sky; roundRect(ctx, px, py, pw, ph, 6 * u); ctx.fill();
  ctx.save(); roundRect(ctx, px, py, pw, ph, 6 * u); ctx.clip();
  ctx.fillStyle = "#F2913D"; ctx.beginPath(); ctx.arc(px + pw * 0.7, py + ph * 0.34, ph * 0.1, 0, Math.PI * 2); ctx.fill();
  const hill = (k, color, lift) => {
    ctx.fillStyle = color; ctx.beginPath(); ctx.moveTo(px, py + ph);
    for (let i = 0; i <= 10; i++) ctx.lineTo(px + (pw * i) / 10, py + ph * (lift - 0.1 * Math.sin(i * 1.1 + k)));
    ctx.lineTo(px + pw, py + ph); ctx.closePath(); ctx.fill();
  };
  hill(0.4, "#9CC8B3", 0.7); hill(2.2, "#2FA77A", 0.88);
  ctx.restore();
  const sx = x + iw * 0.67, sw = iw * 0.29;
  [0.9, 0.55, 0.75, 0.45].forEach((k, i) => { ctx.fillStyle = "#E6E1D7"; roundRect(ctx, sx, py + ih * (0.02 + i * 0.07), sw * k, ih * 0.024, 3 * u); ctx.fill(); });
  const T = mockTarget(x, y, iw, ih);
  ctx.fillStyle = "#3E6FE6"; roundRect(ctx, T.x, T.y, T.w, T.h, T.h / 2); ctx.fill();
  ctx.fillStyle = "rgba(255,255,255,0.85)"; roundRect(ctx, T.x + T.w * 0.25, T.y + T.h * 0.42, T.w * 0.5, T.h * 0.16, 2 * u); ctx.fill();
  const ty = py + ph + ih * 0.07, lanes = [[0, 0.3, 0.32, 0.36], [0.06, 0.48, 0.58, 0.3], [0, 0.22, 0.26, 0.5]];
  lanes.forEach((row, i) => { for (let j = 0; j < row.length; j += 2) { ctx.fillStyle = ["#E6E1D7", "#C9D7F7", "#E6E1D7"][i]; roundRect(ctx, px + iw * 0.93 * row[j], ty + i * ih * 0.055, iw * 0.93 * row[j + 1], ih * 0.035, 3 * u); ctx.fill(); } });
  ctx.restore();
}

// 只用来量字宽（分层时还没有画布）。
let measurer = null;
function measure(text, f) {
  measurer ??= new OffscreenCanvas(1, 1).getContext("2d");
  measurer.font = f;
  return measurer.measureText(text).width;
}

// 每个元素都在画面坐标里画，pose 只给出平移（换场推移 + 入场上移）和不透明度，运行时据此做运动模糊。
function layers(_params, w, h) {
  const u = h / 720, C = STYLE.color, F = STYLE.font, out = [];
  out.push({ draw: (ctx) => { ctx.fillStyle = C.bg; ctx.fillRect(0, 0, w, h); } });

  // 标题：不用卡片。分类色短条先展开，标题随后上移出现，关键词“画面”被荧光笔划出。一屏只划这一处。
  const title = SCENES.title, tx = w * 0.12, ty = h * 0.53, titleFont = font(700, 72 * u, F.title);
  out.push(group(w, u, title, {
    bounds: [tx - 10 * u, ty - 112 * u, tx + 80 * u, ty - 86 * u], rise: 0,
    draw: (ctx, t) => { ctx.fillStyle = C.cats[0]; roundRect(ctx, tx, ty - 104 * u, 48 * u * cubicOut(t / 0.5) + 6 * u, 6 * u, 3 * u); ctx.fill(); },
  }));
  out.push(group(w, u, title, {
    bounds: [tx - 10 * u, ty - 76 * u, tx + 560 * u, ty + 24 * u], delay: 0.12, rise: 20,
    draw: (ctx, t) => {
      ctx.font = titleFont;
      const first = ctx.measureText(COPY.title[0]).width, second = ctx.measureText(COPY.title[1]).width;
      marker(ctx, tx + first - 4 * u, ty, second + 8 * u, 72 * u, (t - 0.6) / 0.4);
      ctx.fillStyle = C.ink;
      ctx.fillText(COPY.title[0] + COPY.title[1], tx, ty);
    },
  }));

  // 花字与关键词：关键词装进一张白卡片（容器统一），卡片标题行用橙色小圆点标出类别；“不走样”字大而重，荧光笔划出。
  const kw = SCENES.keyword, keyFont = font(700, 84 * u, F.title), keyW = measure(COPY.keyword.key, keyFont);
  const cw = keyW + 120 * u, ch = 206 * u, cx0 = w / 2 - cw / 2, cy0 = h * 0.5 - ch / 2;
  out.push(group(w, u, kw, {
    bounds: [cx0 - 40 * u, cy0 - 30 * u, cx0 + cw + 40 * u, cy0 + ch + 50 * u], rise: 26,
    draw: (ctx, t) => {
      card(ctx, cx0, cy0, cw, ch, u);
      ctx.fillStyle = C.cats[1]; ctx.beginPath(); ctx.arc(cx0 + 44 * u, cy0 + 44 * u, 6 * u, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = C.muted; ctx.font = font(500, 22 * u, F.title); ctx.fillText(COPY.keyword.lead, cx0 + 60 * u, cy0 + 52 * u);
      const by = cy0 + 150 * u;
      marker(ctx, cx0 + 56 * u, by, keyW + 8 * u, 84 * u, (t - kw[0] - 0.55) / 0.4);
      ctx.fillStyle = C.ink; ctx.font = keyFont; ctx.fillText(COPY.keyword.key, cx0 + 60 * u, by);
    },
  }));

  // 图片与录屏容器 + 高亮：截图装在白卡片里（卡片标题行写来源“示意画面”），随整屏推入后轻轻上移落定。
  // 高亮：截图其余部分蒙上一层纸色变淡，目标保持清楚，旁边弹出蓝色序号圆“1”，对应口播里的第一步。
  const media = SCENES.media, mw = w * 0.62, mh = mw * 0.6, mx = (w - mw) / 2, my = h * 0.52 - mh / 2;
  const sx = mx + 24 * u, sy = my + 52 * u, sw = mw - 48 * u, sh = mh - 76 * u, T = mockTarget(sx, sy, sw, sh);
  const hl = (t) => cubicOut((t - media[0] - 1.25) / 0.5);
  out.push(group(w, u, media, {
    bounds: [mx - 40 * u, my - 30 * u, mx + mw + 40 * u, my + mh + 50 * u], rise: 26,
    draw: (ctx, t) => {
      card(ctx, mx, my, mw, mh, u);
      ctx.fillStyle = C.cats[0]; ctx.beginPath(); ctx.arc(mx + 30 * u, my + 27 * u, 5 * u, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = C.muted; ctx.font = font(500, 16 * u, F.title); ctx.fillText(COPY.media, mx + 44 * u, my + 33 * u);
      mockScreen(ctx, sx, sy, sw, sh, u);
      const k = hl(t);
      if (k > 0) {
        ctx.save(); roundRect(ctx, sx, sy, sw, sh, 8 * u); ctx.clip();
        ctx.beginPath(); ctx.rect(sx, sy, sw, sh); roundPath(ctx, T.x - 8 * u, T.y - 8 * u, T.w + 16 * u, T.h + 16 * u, (T.h + 16 * u) / 2);
        ctx.fillStyle = `rgba(246,243,236,${0.7 * k})`; ctx.fill("evenodd");
        ctx.restore();
      }
    },
  }));
  out.push({
    bounds: [-22 * u, -22 * u, 22 * u, 22 * u],
    pose: (t) => {
      const k = hl(t), p = phase(t, media);
      if (!p.on || k <= 0) return null;
      // 序号圆跟着卡片一起推移；出现时从 70% 放大到 100%（贴纸式的小元素才放大）。
      return { x: T.x + T.w + 30 * u + push(t, media, w), y: T.y + T.h / 2, scale: 0.7 + 0.3 * k, opacity: Math.min(1, k * 2) * (1 - p.leave) };
    },
    draw: (ctx) => numberBadge(ctx, 0, 0, 20 * u, 1, C.cats[0]),
  });

  // 数据：环形图与计数随整屏推入；右侧结论被荧光笔划出。不再加一句复述数字的解释。
  const data = SCENES.data, dcx = w * 0.36, dcy = h * 0.5, r = 120 * u, lx = w * 0.56, ly = h * 0.52;
  out.push(group(w, u, data, {
    bounds: [dcx - r - 20 * u, dcy - r - 20 * u, dcx + r + 20 * u, dcy + r + 20 * u], rise: 0,
    draw: (ctx, t) => {
      const k = cubicOut((t - data[0] - 0.2) / 1.1) * (COPY.data.value / 100);
      donut(ctx, dcx, dcy, r, k, u);
      ctx.textAlign = "center";
      ctx.fillStyle = C.ink;
      ctx.font = font(500, 76 * u, F.number);
      ctx.fillText(`${Math.round(k * 100)}`, dcx - 12 * u, dcy + 26 * u);
      ctx.font = font(500, 30 * u, F.number);
      ctx.fillText(COPY.data.unit, dcx + 52 * u, dcy + 24 * u);
      ctx.textAlign = "left";
    },
  }));
  out.push(group(w, u, data, {
    bounds: [lx - 10 * u, ly - 50 * u, lx + 320 * u, ly + 20 * u], delay: 0.35, rise: 14,
    draw: (ctx, t) => {
      ctx.font = font(700, 44 * u, F.title);
      marker(ctx, lx - 4 * u, ly, ctx.measureText(COPY.data.label).width + 8 * u, 44 * u, (t - data[0] - 0.75) / 0.4);
      ctx.fillStyle = C.ink;
      ctx.fillText(COPY.data.label, lx, ly);
    },
  }));

  // 人名条：白色小卡片，左侧分类色圆形头像（用姓氏），右侧名字与职位。
  const name = SCENES.name, nx = w * 0.08, ny = h * 0.74, bw = 280 * u, bh = 76 * u;
  out.push(group(w, u, name, {
    bounds: [nx - 40 * u, ny - 30 * u, nx + bw + 40 * u, ny + bh + 50 * u], rise: 24,
    draw: (ctx) => {
      card(ctx, nx, ny, bw, bh, u);
      ctx.fillStyle = C.cats[1];
      ctx.beginPath(); ctx.arc(nx + 38 * u, ny + bh / 2, 22 * u, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = "#FFFFFF";
      ctx.font = font(700, 20 * u, F.title);
      ctx.textAlign = "center";
      ctx.fillText(COPY.name.name[0], nx + 38 * u, ny + bh / 2 + 7 * u);
      ctx.textAlign = "left";
      ctx.fillStyle = C.ink;
      ctx.font = font(700, 26 * u, F.title);
      ctx.fillText(COPY.name.name, nx + 76 * u, ny + 36 * u);
      ctx.fillStyle = C.muted;
      ctx.font = font(400, 16 * u, F.title);
      ctx.fillText(COPY.name.role, nx + 76 * u, ny + 58 * u);
    },
  }));

  // 收尾：一句话随整屏推入，关键词随后被荧光笔划出。
  const end = SCENES.end;
  out.push(group(w, u, end, {
    bounds: [w * 0.2, h * 0.53 - 60 * u, w * 0.8, h * 0.53 + 20 * u], rise: 16,
    draw: (ctx, t) => {
      ctx.font = font(700, 54 * u, F.title);
      const a = ctx.measureText(COPY.end[0]).width, b = ctx.measureText(COPY.end[1]).width;
      const x = (w - a - b) / 2, y = h * 0.53;
      marker(ctx, x + a - 4 * u, y, b + 8 * u, 54 * u, (t - end[0] - 0.55) / 0.4);
      ctx.fillStyle = C.ink;
      ctx.fillText(COPY.end[0] + COPY.end[1], x, y);
    },
  }));
  return out;
}

export default {
  name: "知识讲解 · 样片", kind: "generator", mode: "dynamic",
  nameEnglish: "Explainer · Sample",
  params: [],
  // 动作温和，180° 快门下只有换场推移和上移时有轻微拖影。
  motionBlur: { shutter: 180 },
  layers,
};
